"""Planning scenarios in 2026 USD. Allowances are estimates, not quotes."""
from html import escape

BUDGETS = [
 dict(low=20000,high=40000,target=30000,monthly=4000,
      outcome='Launch a founder-led AI, creative and training service, with modest printing capability and three months of operating cash.',
      startup=[('Computers, audiovisual tools and initial software setup',6000),('Compact printing and finishing equipment',5000),('Business setup, insurance deposits and shared-space setup',2500),('Initial materials, launch samples and marketing',1500),('Contingency, freight and tax allowance',3000)],
      operating=[('Contract help, consumables and outsourced production',2000),('Software and hosting',500),('Shared workspace and event rooms',500),('Insurance and administration',500),('Marketing, travel and miscellaneous',500)]),
 dict(low=100000,high=200000,target=150000,monthly=15000,
      outcome='Open an approximately 2,000 sq ft hub with a coffee corner, worktables, upgraded print production, a small 3D-printer fleet and three months of operating cash.',
      startup=[('Lease deposits and light fit-out of suitable premises',35000),('Additional printing, finishing and 3D equipment',30000),('Coffee corner, furniture, worktables and starter stock',20000),('Move-in, professional fees and launch setup',10000),('Contingency, freight and tax allowance',10000)],
      operating=[('Rent, building charges and utilities',5500),('Staff, payroll costs and contract support',6000),('Software, insurance and administration',1500),('Materials and outsourced production',2000)]),
 dict(low=350000,high=800000,target=600000,monthly=60000,
      outcome='Expand into approximately 6,000 sq ft with a café/kitchen, stage, maker retail and a selected fabrication workshop, plus three months of operating cash.',
      startup=[('Lease deposits, fit-out, power, extraction and separations',130000),('Additional fabrication, print and 3D equipment',140000),('Café/kitchen equipment, stage and furnishings',45000),('Moving, professional fees, training and added stock',30000),('Contingency, freight and tax allowance',75000)],
      operating=[('Rent, building charges and utilities',18000),('Staff, payroll costs and contract support',30000),('Materials, outsourced work and machine upkeep',8000),('Insurance, software and administration',4000)])
]

def money(n): return '$'+format(n,',')
def budget_range(b):return money(b['low'])+'–'+money(b['high'])

def phase_budget(i):
 b=BUDGETS[i];startup=sum(n for _,n in b['startup']);reserve=3*b['monthly']
 assert startup+reserve==b['target'] and sum(n for _,n in b['operating'])==b['monthly']
 rows=''.join('<tr><th scope="row">'+escape(k)+'</th><td>'+money(n)+'</td></tr>' for k,n in b['startup'])
 ops=''.join('<tr><th scope="row">'+escape(k)+'</th><td>'+money(n)+'</td></tr>' for k,n in b['operating'])
 return f'''<div class="phase-budget"><span class="eyebrow">What the funding could make possible</span><h4>{budget_range(b)}</h4><p class="budget-basis">Estimated {'launch funding' if i==0 else 'additional funding at this phase'} · 2026 USD</p><p>{b['outcome']}</p><div class="budget-example"><strong>A {money(b['target'])} example</strong><span>{money(startup)} to set up + {money(reserve)} operating reserve</span></div><details class="budget-detail"><summary>See the example budget</summary><div class="budget-table-wrap"><table><caption>Phase {i+1}: one illustrative allocation</caption><tbody>{rows}<tr class="budget-subtotal"><th scope="row">Setup subtotal</th><td>{money(startup)}</td></tr><tr><th scope="row">Three months of operating cash</th><td>{money(reserve)}</td></tr></tbody><tfoot><tr><th scope="row">Example funding total</th><td>{money(b['target'])}</td></tr></tfoot></table><table><caption>Monthly operating allowance behind the reserve</caption><tbody>{ops}</tbody><tfoot><tr><th scope="row">Monthly total, before customer receipts</th><td>{money(b['monthly'])}</td></tr></tfoot></table></div></details></div>'''

def budget_assumptions():
 return '''<details class="budget-assumptions"><summary>How we estimated the costs</summary><p><strong>Planning estimates as of October 24, 2026.</strong> The ranges are our allowances for three different scales of operation, informed by public equipment prices and local asking rents. They are not supplier or construction quotes.</p><ul><li><strong>Additional funding, not cumulative totals.</strong> Phase 2 and Phase 3 assume useful earlier equipment stays in use; the equipment lines fund additions. The three example steps total $780,000 if completed in sequence. Future profits, landlord contributions or contributed equipment could reduce outside cash needed.</li><li><strong>Founder-led at first.</strong> Phase 1 allows flexible contract support; Phase 2 allows a modest mix of staff and contractors; Phase 3 allows a larger production/café team. Full founder salaries are excluded. Staffing and owner compensation need a separate operating plan before commitments.</li><li><strong>Three-month reserve.</strong> Each example includes three months of estimated gross operating costs before customer receipts. This is a cash cushion, not a prediction of break-even. Financing payments are excluded and would increase cash needs.</li><li><strong>Lease suitable premises.</strong> Phase 2 assumes light alterations to an approximately 2,000 sq ft unit. Phase 3 assumes about 6,000 sq ft with a workable shell. Major structural work, unusual fire or utility upgrades, or a full restaurant build could exceed these ranges. No building purchase is included.</li><li><strong>Selected machines, not every machine.</strong> Phase 3 includes a practical mix of fabrication and print equipment. A full industrial fiber-laser/waterjet line is outside this example. Shipping and purchase taxes are allowances within contingency; each quote still needs installed-cost review.</li></ul><p><strong>Price anchors:</strong> Brother lists its <a href="https://www.brother-usa.com/p/laser-printers/MFCL8905CDW" target="_blank" rel="noopener">MFC-L8905CDW at $769.99</a>, an office-class starting point rather than a full print-shop press. ShopBot lists its <a href="https://shopbottools.com/products/desktop-max/" target="_blank" rel="noopener">Desktop MAX CNC from $12,548</a>, before relevant extras and installation. <a href="https://www.cityfeet.com/cont/post-falls-id/retail-space-for-lease" target="_blank" rel="noopener">Post Falls listings</a> include asking rents around $15–$32 per sq ft per year; building charges, utilities and permitted uses vary. These examples show why installed equipment and premises budgets are larger than a machine’s advertised price.</p></details>'''

def investment_budget_summary():
 rows=''.join(f'<tr><th scope="row"><a href="tink-town.html#growth-{i+1}">Phase {i+1} · {label}</a></th><td>{budget_range(b)}</td><td>{"Launch funding" if i==0 else "Additional funding"}</td></tr>' for i,(label,b) in enumerate(zip(['Service launch','Small hub','Expanded workshop'],BUDGETS)))
 return f'''<section class="section investment-phase-budgets" id="phase-funding"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Put an amount beside the ambition</span><h2>What could your<br>capital help build?</h2></div><p>Back a defined step. Tink Town can launch as a lean service business, then grow into a public hub and a larger workshop as demand supports it.</p></div><div class="budget-table-wrap"><table><caption>Illustrative phase funding · 2026 USD</caption><thead><tr><th scope="col">The step</th><th scope="col">Planning range</th><th scope="col">Basis</th></tr></thead><tbody>{rows}</tbody></table></div><p class="budget-summary-note">Each range includes setup, a contingency allowance and three months of operating cash. Later figures are additional funding, not totals to date. The example scenarios are $30,000, $150,000 and $600,000 respectively; full founder salaries, financing payments and a building purchase are excluded.</p><a class="text-link" href="tink-town.html#growth">Explore the phase budgets and assumptions <span aria-hidden="true">↗</span></a></div></section>'''
